// src/AdminPerfilPage.js
import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import api from "./api/apiClient";
import logo from "./assets/logo-cancha.png";

// ========== ENDPOINT DEL PERFIL DEL CLUB ==========
// Si tu backend usa otra ruta, cámbiala aquí:
const CLUB_PROFILE_ENDPOINT = "/api/accounts/club/perfil/";

// Normaliza lo que viene del backend a un objeto plano
function normalizarPerfilClub(data) {
  if (!data) data = {};

  const admin =
    data.admin_principal ||
    data.administrador ||
    data.admin ||
    {};

  // helper para hora (acepta "08:00", "08:00:00", etc.)
  const toTime = (v) => {
    if (!v) return "";
    const s = String(v);
    if (s.length >= 5) return s.slice(0, 5); // "HH:MM"
    return s;
  };

  return {
    id: data.id ?? null,
    nombreClub:
      data.nombre_club ??
      data.nombre ??
      data.name ??
      "",
    ruc:
      data.ruc ??
      data.ruc_numero ??
      "",
    telefonoPrincipal:
      data.telefono_principal ??
      data.telefono ??
      data.phone ??
      "",
    emailContacto:
      data.email_contacto ??
      data.correo_contacto ??
      data.email ??
      "",
    direccion:
      data.direccion ??
      data.direccion_club ??
      "",
    horaApertura: toTime(
      data.hora_apertura ??
      data.apertura ??
      data.hora_apertura_club
    ),
    horaCierre: toTime(
      data.hora_cierre ??
      data.cierre ??
      data.hora_cierre_club
    ),
    descripcion:
      data.descripcion ??
      data.descripcion_club ??
      "",
    sitioWeb:
      data.sitio_web ??
      data.web ??
      data.url ??
      "",

    adminNombre:
      admin.nombre_completo ??
      admin.nombre ??
      admin.name ??
      "",
    adminDni:
      admin.dni ??
      admin.documento ??
      "",
    adminCargo:
      admin.cargo ??
      admin.rol ??
      "",
    adminTelefono:
      admin.telefono_personal ??
      admin.telefono ??
      "",
    adminEmail:
      admin.email_personal ??
      admin.email ??
      "",
  };
}

// Convierte el estado plano al payload que espera el backend
function construirPayload(perfil) {
  return {
    // Datos del club
    nombre_club: perfil.nombreClub,
    ruc: perfil.ruc,
    telefono_principal: perfil.telefonoPrincipal,
    email_contacto: perfil.emailContacto,
    direccion: perfil.direccion,
    hora_apertura: perfil.horaApertura || null,
    hora_cierre: perfil.horaCierre || null,
    descripcion: perfil.descripcion,
    sitio_web: perfil.sitioWeb,

    // Datos del administrador principal (si tu backend no los usa,
    // simplemente los ignorará o puedes adaptarlos a tu serializer)
    admin_nombre_completo: perfil.adminNombre,
    admin_dni: perfil.adminDni,
    admin_cargo: perfil.adminCargo,
    admin_telefono_personal: perfil.adminTelefono,
    admin_email_personal: perfil.adminEmail,
  };
}

export default function AdminPerfilPage() {
  const [perfil, setPerfil] = useState(() =>
    normalizarPerfilClub({})
  );
  const [loading, setLoading] = useState(true);
  const [editando, setEditando] = useState(false);
  const [guardando, setGuardando] = useState(false);
  const [errorMsg, setErrorMsg] = useState(null);
  const [successMsg, setSuccessMsg] = useState(null);

  // Copia local para poder "Cancelar" sin perder la versión original
  const [perfilOriginal, setPerfilOriginal] = useState(null);

  // ===== cargar perfil al iniciar =====
  useEffect(() => {
    const cargarPerfil = async () => {
      try {
        setLoading(true);
        setErrorMsg(null);

        const res = await api.get(CLUB_PROFILE_ENDPOINT);
        const data =
          res.data?.club ??
          res.data?.perfil ??
          res.data;
        const norm = normalizarPerfilClub(data);

        setPerfil(norm);
        setPerfilOriginal(norm);
      } catch (error) {
        console.error("Error cargando perfil del club", error);
        const detalle =
          error.response?.data?.detalle ||
          error.response?.data?.mensaje ||
          error.response?.data?.error ||
          "Ocurrió un error al cargar el perfil del club.";
        setErrorMsg(detalle);
      } finally {
        setLoading(false);
      }
    };

    cargarPerfil();
  }, []);

  const onChangePerfil = (e) => {
    const { name, value } = e.target;
    setPerfil((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const empezarEditar = () => {
    setEditando(true);
    setSuccessMsg(null);
    setErrorMsg(null);
    setPerfilOriginal(perfil);
  };

  const cancelarEdicion = () => {
    setEditando(false);
    setErrorMsg(null);
    setSuccessMsg(null);
    if (perfilOriginal) {
      setPerfil(perfilOriginal);
    }
  };

  const guardarCambios = async (e) => {
    e.preventDefault();
    if (guardando) return;

    try {
      setGuardando(true);
      setErrorMsg(null);
      setSuccessMsg(null);

      const payload = construirPayload(perfil);

      // PUT al endpoint (si tu backend usa PATCH, puedes cambiarlo)
      await api.put(CLUB_PROFILE_ENDPOINT, payload);

      setSuccessMsg("Los cambios se guardaron correctamente.");
      setEditando(false);
      setPerfilOriginal(perfil);
    } catch (error) {
      console.error("Error guardando perfil del club", error);
      const detalle =
        error.response?.data?.detalle ||
        error.response?.data?.mensaje ||
        error.response?.data?.error ||
        JSON.stringify(error.response?.data || "") ||
        "Ocurrió un error al guardar el perfil.";
      setErrorMsg(detalle);
    } finally {
      setGuardando(false);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col">
        <header className="bg-white border-b border-slate-200">
          <div className="max-w-6xl mx-auto flex items-center justify-between px-8 py-4">
            <div className="flex items-center gap-2">
              <img src={logo} alt="CanchaYa logo" className="w-7 h-7" />
              <span className="font-bold text-xl text-blue-700">CanchaYa</span>
            </div>
          </div>
        </header>

        <main className="flex-1 flex items-center justify-center">
          <p className="text-sm text-slate-500">
            Cargando configuración del club...
          </p>
        </main>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      {/* NAVBAR CLUB */}
      <header className="bg-white border-b border-slate-200">
        <div className="max-w-6xl mx-auto flex items-center justify-between px-8 py-4">
          <div className="flex items-center gap-2">
            <img src={logo} alt="CanchaYa logo" className="w-7 h-7" />
            <span className="font-bold text-xl text-blue-700">CanchaYa</span>
          </div>

          <nav className="flex items-center gap-6 text-sm">
            <Link to="/club/home" className="text-slate-700">
              Inicio
            </Link>
            <Link to="/club/canchas" className="text-slate-700">
              Canchas
            </Link>
            <Link to="/club/reservas" className="text-slate-700">
              Reservas
            </Link>
            <span className="px-4 py-2 rounded-full bg-slate-900 text-white font-semibold text-sm">
              Perfil
            </span>

            <Link
              to="/login"
              className="ml-4 inline-flex items-center gap-2 px-4 py-2 rounded-xl border border-slate-200 text-sm font-semibold text-slate-800 bg-white hover:bg-slate-50"
            >
              <span>↪</span>
              <span>Cerrar Sesión</span>
            </Link>
          </nav>
        </div>
      </header>

      {/* CONTENIDO */}
      <main className="flex-1">
        <section className="max-w-6xl mx-auto px-8 py-8">
          <div className="flex items-center justify-between mb-6">
            <div>
              <h1 className="text-xl font-semibold text-slate-900">
                Perfil del Club
              </h1>
              <p className="text-sm text-slate-500">
                Visualiza y actualiza la información general de tu club deportivo.
              </p>
            </div>

            {!editando ? (
              <button
                type="button"
                onClick={empezarEditar}
                className="inline-flex items-center gap-2 px-4 py-2 rounded-xl bg-slate-900 text-white text-sm font-semibold hover:bg-slate-800"
              >
                <span>✎</span>
                <span>Editar Perfil</span>
              </button>
            ) : (
              <div className="flex gap-2">
                <button
                  type="button"
                  onClick={cancelarEdicion}
                  className="px-4 py-2 rounded-xl border border-slate-200 text-xs font-semibold text-slate-700 bg-white hover:bg-slate-50"
                  disabled={guardando}
                >
                  Cancelar
                </button>
                <button
                  type="button"
                  onClick={guardarCambios}
                  className="px-4 py-2 rounded-xl bg-slate-900 text-white text-xs font-semibold hover:bg-slate-800 disabled:opacity-60 disabled:cursor-not-allowed"
                  disabled={guardando}
                >
                  {guardando ? "Guardando..." : "Guardar Cambios"}
                </button>
              </div>
            )}
          </div>

          {errorMsg && (
            <p className="mb-4 text-xs text-red-600 whitespace-pre-wrap">
              {errorMsg}
            </p>
          )}
          {successMsg && (
            <p className="mb-4 text-xs text-emerald-600 whitespace-pre-wrap">
              {successMsg}
            </p>
          )}

          {/* GRID PRINCIPAL: primero Administrador, luego datos del club */}
          <form
            className="space-y-6 text-sm"
            onSubmit={guardarCambios}
          >
            {/* ADMINISTRADOR PRINCIPAL */}
            <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6">
              <h2 className="text-sm font-semibold text-slate-900 mb-1">
                Administrador Principal
              </h2>
              <p className="text-xs text-slate-500 mb-4">
                Información de contacto de la persona responsable del club.
              </p>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-semibold text-slate-700 mb-1">
                    Nombre completo
                  </label>
                  <input
                    type="text"
                    name="adminNombre"
                    value={perfil.adminNombre}
                    onChange={onChangePerfil}
                    disabled={!editando}
                    className={
                      "w-full rounded-xl border px-3 py-2 text-sm " +
                      (editando
                        ? "border-slate-200 bg-white"
                        : "border-slate-100 bg-slate-50 text-slate-600")
                    }
                  />
                </div>

                <div>
                  <label className="block text-xs font-semibold text-slate-700 mb-1">
                    DNI
                  </label>
                  <input
                    type="text"
                    name="adminDni"
                    value={perfil.adminDni}
                    onChange={onChangePerfil}
                    disabled={!editando}
                    className={
                      "w-full rounded-xl border px-3 py-2 text-sm " +
                      (editando
                        ? "border-slate-200 bg-white"
                        : "border-slate-100 bg-slate-50 text-slate-600")
                    }
                  />
                </div>

                <div>
                  <label className="block text-xs font-semibold text-slate-700 mb-1">
                    Cargo
                  </label>
                  <input
                    type="text"
                    name="adminCargo"
                    value={perfil.adminCargo}
                    onChange={onChangePerfil}
                    disabled={!editando}
                    className={
                      "w-full rounded-xl border px-3 py-2 text-sm " +
                      (editando
                        ? "border-slate-200 bg-white"
                        : "border-slate-100 bg-slate-50 text-slate-600")
                    }
                  />
                </div>

                <div>
                  <label className="block text-xs font-semibold text-slate-700 mb-1">
                    Teléfono personal
                  </label>
                  <input
                    type="text"
                    name="adminTelefono"
                    value={perfil.adminTelefono}
                    onChange={onChangePerfil}
                    disabled={!editando}
                    className={
                      "w-full rounded-xl border px-3 py-2 text-sm " +
                      (editando
                        ? "border-slate-200 bg-white"
                        : "border-slate-100 bg-slate-50 text-slate-600")
                    }
                  />
                </div>

                <div className="md:col-span-2">
                  <label className="block text-xs font-semibold text-slate-700 mb-1">
                    Email personal
                  </label>
                  <input
                    type="email"
                    name="adminEmail"
                    value={perfil.adminEmail}
                    onChange={onChangePerfil}
                    disabled={!editando}
                    className={
                      "w-full rounded-xl border px-3 py-2 text-sm " +
                      (editando
                        ? "border-slate-200 bg-white"
                        : "border-slate-100 bg-slate-50 text-slate-600")
                    }
                  />
                </div>
              </div>
            </div>

            {/* INFORMACIÓN GENERAL + CONFIGURACIÓN OPERATIVA */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
              {/* Información general del club */}
              <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6">
                <h2 className="text-sm font-semibold text-slate-900 mb-1">
                  Información General
                </h2>
                <p className="text-xs text-slate-500 mb-4">
                  Datos básicos del club que se muestran a los deportistas.
                </p>

                <div className="space-y-3">
                  <div>
                    <label className="block text-xs font-semibold text-slate-700 mb-1">
                      Nombre del club
                    </label>
                    <input
                      type="text"
                      name="nombreClub"
                      value={perfil.nombreClub}
                      onChange={onChangePerfil}
                      disabled={!editando}
                      className={
                        "w-full rounded-xl border px-3 py-2 text-sm " +
                        (editando
                          ? "border-slate-200 bg-white"
                          : "border-slate-100 bg-slate-50 text-slate-600")
                      }
                    />
                  </div>

                  <div>
                    <label className="block text-xs font-semibold text-slate-700 mb-1">
                      RUC / NIT
                    </label>
                    <input
                      type="text"
                      name="ruc"
                      value={perfil.ruc}
                      onChange={onChangePerfil}
                      disabled={!editando}
                      className={
                        "w-full rounded-xl border px-3 py-2 text-sm " +
                        (editando
                          ? "border-slate-200 bg-white"
                          : "border-slate-100 bg-slate-50 text-slate-600")
                      }
                    />
                  </div>

                  <div>
                    <label className="block text-xs font-semibold text-slate-700 mb-1">
                      Teléfono principal
                    </label>
                    <input
                      type="text"
                      name="telefonoPrincipal"
                      value={perfil.telefonoPrincipal}
                      onChange={onChangePerfil}
                      disabled={!editando}
                      className={
                        "w-full rounded-xl border px-3 py-2 text-sm " +
                        (editando
                          ? "border-slate-200 bg-white"
                          : "border-slate-100 bg-slate-50 text-slate-600")
                      }
                    />
                  </div>

                  <div>
                    <label className="block text-xs font-semibold text-slate-700 mb-1">
                      Email de contacto
                    </label>
                    <input
                      type="email"
                      name="emailContacto"
                      value={perfil.emailContacto}
                      onChange={onChangePerfil}
                      disabled={!editando}
                      className={
                        "w-full rounded-xl border px-3 py-2 text-sm " +
                        (editando
                          ? "border-slate-200 bg-white"
                          : "border-slate-100 bg-slate-50 text-slate-600")
                      }
                    />
                  </div>

                  <div>
                    <label className="block text-xs font-semibold text-slate-700 mb-1">
                      Dirección
                    </label>
                    <input
                      type="text"
                      name="direccion"
                      value={perfil.direccion}
                      onChange={onChangePerfil}
                      disabled={!editando}
                      className={
                        "w-full rounded-xl border px-3 py-2 text-sm " +
                        (editando
                          ? "border-slate-200 bg-white"
                          : "border-slate-100 bg-slate-50 text-slate-600")
                      }
                    />
                  </div>
                </div>
              </div>

              {/* Configuración operativa */}
              <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6">
                <h2 className="text-sm font-semibold text-slate-900 mb-1">
                  Configuración Operativa
                </h2>
                <p className="text-xs text-slate-500 mb-4">
                  Horarios y descripción general del club.
                </p>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-3">
                  <div>
                    <label className="block text-xs font-semibold text-slate-700 mb-1">
                      Hora de apertura
                    </label>
                    <input
                      type="time"
                      name="horaApertura"
                      value={perfil.horaApertura}
                      onChange={onChangePerfil}
                      disabled={!editando}
                      className={
                        "w-full rounded-xl border px-3 py-2 text-sm " +
                        (editando
                          ? "border-slate-200 bg-white"
                          : "border-slate-100 bg-slate-50 text-slate-600")
                      }
                    />
                  </div>

                  <div>
                    <label className="block text-xs font-semibold text-slate-700 mb-1">
                      Hora de cierre
                    </label>
                    <input
                      type="time"
                      name="horaCierre"
                      value={perfil.horaCierre}
                      onChange={onChangePerfil}
                      disabled={!editando}
                      className={
                        "w-full rounded-xl border px-3 py-2 text-sm " +
                        (editando
                          ? "border-slate-200 bg-white"
                          : "border-slate-100 bg-slate-50 text-slate-600")
                      }
                    />
                  </div>
                </div>

                <div className="mb-3">
                  <label className="block text-xs font-semibold text-slate-700 mb-1">
                    Descripción del club
                  </label>
                  <textarea
                    name="descripcion"
                    value={perfil.descripcion}
                    onChange={onChangePerfil}
                    disabled={!editando}
                    className={
                      "w-full rounded-xl border px-3 py-2 text-sm min-h-[80px] " +
                      (editando
                        ? "border-slate-200 bg-white"
                        : "border-slate-100 bg-slate-50 text-slate-600")
                    }
                    placeholder="Describe brevemente tu club, instalaciones y servicios..."
                  />
                </div>

                <div>
                  <label className="block text-xs font-semibold text-slate-700 mb-1">
                    Sitio web
                  </label>
                  <input
                    type="url"
                    name="sitioWeb"
                    value={perfil.sitioWeb}
                    onChange={onChangePerfil}
                    disabled={!editando}
                    className={
                      "w-full rounded-xl border px-3 py-2 text-sm " +
                      (editando
                        ? "border-slate-200 bg-white"
                        : "border-slate-100 bg-slate-50 text-slate-600")
                    }
                    placeholder="https://tusitio.com"
                  />
                </div>
              </div>
            </div>
          </form>
        </section>
      </main>
    </div>
  );
}
